package com.kaipai.model.ai.dto; import java.util.*; import lombok.Data; @Data public class ProfileImportApplyReqDTO { private String requestId; private String scene; private Long profileVersion; private Long workLibraryVersion; private Long avatarAssetId; private List<ConfirmedCandidate> profileCandidates=new ArrayList<>(); private List<ConfirmedWork> works=new ArrayList<>(); @Data public static class ConfirmedCandidate { private String candidateId; private String fieldKey; private String value; private String sourceType; private boolean confirmed; private boolean requiresExplicitConfirmation; private String proof; } @Data public static class ConfirmedWork { private String candidateId; private String sourceType; private boolean confirmed; private String proof; private String projectName; private String roleName; private String publishStatus; private String workTypeCode; private String roleLevelCode; private Integer shootYear; private Integer shootMonth; private String platform; private String syncSoundStatus; private List<String> collaborators=new ArrayList<>(); private String achievementText; private String description; public String proofValue(){return String.join("|",safe(projectName),safe(roleName),safe(publishStatus),safe(workTypeCode),safe(roleLevelCode),safe(shootYear),safe(shootMonth),safe(platform),safe(syncSoundStatus),String.join(",",collaborators),safe(achievementText),safe(description));} private String safe(Object value){return value==null?"":String.valueOf(value);} } }
